// Manually maintained library queries. This file is not generated by sqlc.
package database

import (
	"context"
	"database/sql"
	"strings"
)

type LibraryParams struct {
	ParentFolderID string
	FolderID       string
	UserID         sql.NullString
	Query          string
	Sort           string
	Order          string
}

// GetLibraryContents searches the accessible library globally only when Query is
// nonempty; otherwise it lists the requested folder. All values are parameters.
func (q *Queries) GetLibraryContents(ctx context.Context, arg LibraryParams) ([]GetFolderContentsRow, error) {
	column := "Date_Added"
	switch arg.Sort {
	case "name":
		column = "Name"
	case "size":
		column = "Size"
	}
	direction := "DESC"
	if arg.Order == "asc" {
		direction = "ASC"
	}
	folderFilter, fileFilter := "Parent_Folder_ID = ?", "Folder_ID = ?"
	folderValue, fileValue := arg.ParentFolderID, arg.FolderID
	if arg.Query != "" {
		// Use an explicit escape character, independent of MySQL backslash modes.
		pattern := "%" + strings.NewReplacer("!", "!!", "%", "!%", "_", "!_").Replace(arg.Query) + "%"
		folderFilter, fileFilter = "Name LIKE ? ESCAPE '!'", "Name LIKE ? ESCAPE '!'"
		folderValue, fileValue = pattern, pattern
	}
	query := `SELECT type, ID, Name, Size, Date_Added, Server FROM (
 SELECT 'folder' AS type, ID, Name, Size, DATE_FORMAT(Date_Added, '%Y-%m-%d %H:%i:%s') AS Date_Added, '' AS Server
 FROM Folders WHERE ` + folderFilter + ` AND ID != '00000000-0000-0000-0000-000000000000' AND (User_ID IS NULL OR User_ID = ?)
 UNION ALL
 SELECT 'file' AS type, ID, Name, Size, DATE_FORMAT(Date_Added, '%Y-%m-%d %H:%i:%s') AS Date_Added, Server
 FROM Files WHERE ` + fileFilter + ` AND (User_ID IS NULL OR User_ID = ?)
 ) AS library ORDER BY ` + column + ` ` + direction + `, Name ASC, ID ASC`
	rows, err := q.db.QueryContext(ctx, query, folderValue, arg.UserID, fileValue, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetFolderContentsRow
	for rows.Next() {
		var item GetFolderContentsRow
		if err := rows.Scan(&item.Type, &item.ID, &item.Name, &item.Size, &item.DateAdded, &item.Server); err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	return items, rows.Err()
}

func (q *Queries) GetLibraryContentOwner(ctx context.Context, id, contentType string) (sql.NullString, error) {
	query := "SELECT User_ID FROM Files WHERE ID = ?"
	if contentType == "folder" {
		query = "SELECT User_ID FROM Folders WHERE ID = ?"
	}
	var owner sql.NullString
	err := q.db.QueryRowContext(ctx, query, id).Scan(&owner)
	return owner, err
}

// LibrarySubtreeOwned rejects mixed-ownership subtrees, including public content.
// UNION (not UNION ALL) also terminates safely if corrupt data contains a cycle.
func (q *Queries) LibrarySubtreeOwned(ctx context.Context, id, userID string) (bool, error) {
	const query = `WITH RECURSIVE subtree AS (
 SELECT ID FROM Folders WHERE ID = ?
 UNION DISTINCT SELECT f.ID FROM Folders f JOIN subtree s ON f.Parent_Folder_ID = s.ID
 ) SELECT (
 (SELECT COUNT(*) FROM Folders f JOIN subtree s ON f.ID = s.ID WHERE f.User_ID IS NULL OR f.User_ID != ?) +
 (SELECT COUNT(*) FROM Files f JOIN subtree s ON f.Folder_ID = s.ID WHERE f.User_ID IS NULL OR f.User_ID != ?)
 ) = 0`
	var owned bool
	err := q.db.QueryRowContext(ctx, query, id, userID, userID).Scan(&owned)
	return owned, err
}
